AMojuloMenuGameMode::AMojuloMenuGameMode()
{
    PrimaryActorTick.bCanEverTick = true;
    bStartPlayersAsSpectators = true;
    HUDClass = AMojuloMenuHUD::StaticClass();
}

void AMojuloMenuGameMode::BeginPlay()
{
    Super::BeginPlay();
    MojuloScore::LoadGame(Game);
    Done = MojuloScore::ReadCompleted();
    APlayerController* PC = UGameplayStatics::GetPlayerController(this, 0);
    if (PC != nullptr) { PC->bShowMouseCursor = true; PC->SetIgnoreMoveInput(true); }
    USoundWave* Wave = LoadObject<USoundWave>(nullptr, TEXT("/Game/MojuloPack/Audio/menu.menu"));
    if (Wave != nullptr) UGameplayStatics::SpawnSound2D(this, Wave);
}

bool AMojuloMenuGameMode::IsLocked(const FMojuloGameLevel& Level) const
{
    return !Level.GateCompleted.IsEmpty() && !Done.Contains(Level.GateCompleted);
}

void AMojuloMenuGameMode::Tick(float DeltaSeconds)
{
    Super::Tick(DeltaSeconds);
    if (Game.Levels.Num() == 0) return;
    APlayerController* PC = UGameplayStatics::GetPlayerController(this, 0);
    if (PC == nullptr) return;
    if (PC->WasInputKeyJustPressed(EKeys::Down) || PC->WasInputKeyJustPressed(EKeys::S))
        Selected = (Selected + 1) % Game.Levels.Num();
    if (PC->WasInputKeyJustPressed(EKeys::Up) || PC->WasInputKeyJustPressed(EKeys::W))
        Selected = (Selected + Game.Levels.Num() - 1) % Game.Levels.Num();
    if (PC->WasInputKeyJustPressed(EKeys::Enter) || PC->WasInputKeyJustPressed(EKeys::SpaceBar))
    {
        const FMojuloGameLevel& Level = Game.Levels[Selected];
        if (!IsLocked(Level))
            UGameplayStatics::OpenLevel(this, FName(*MojuloScore::MapPath(Level.Ref)));
    }
}

void AMojuloMenuHUD::DrawHUD()
{
    Super::DrawHUD();
    AMojuloMenuGameMode* Mode = GetWorld() ? GetWorld()->GetAuthGameMode<AMojuloMenuGameMode>() : nullptr;
    if (Mode == nullptr || Canvas == nullptr) return;
    UFont* Font = GEngine->GetLargeFont();

    float W = 0.f, H = 0.f;
    GetTextSize(Mode->Game.Title, W, H, Font, 2.6f);
    float Y = Canvas->SizeY * 0.22f;
    DrawText(Mode->Game.Title, FLinearColor::White, (Canvas->SizeX - W) / 2.f, Y, Font, 2.6f);
    Y += H + 40.f;

    for (int32 i = 0; i < Mode->Game.Levels.Num(); i++)
    {
        const FMojuloGameLevel& Level = Mode->Game.Levels[i];
        FString Label = Level.Title.IsEmpty() ? Level.Ref : Level.Title;
        if (Mode->Done.Contains(Level.Ref)) Label += TEXT("  [done]");
        const bool bLocked = Mode->IsLocked(Level);
        if (bLocked) Label += TEXT("  [locked]");
        if (i == Mode->Selected) Label = TEXT("> ") + Label;
        const FLinearColor Color = bLocked ? FLinearColor(0.45f, 0.45f, 0.45f)
            : (i == Mode->Selected ? FLinearColor(0.98f, 0.85f, 0.25f) : FLinearColor::White);
        GetTextSize(Label, W, H, Font, 1.6f);
        DrawText(Label, Color, (Canvas->SizeX - W) / 2.f, Y, Font, 1.6f);
        Y += H + 18.f;
    }
    DrawText(TEXT("Up/Down select \u00b7 Enter play \u00b7 M returns here from a level"),
        FLinearColor(0.7f, 0.7f, 0.7f), 16.f, Canvas->SizeY - 40.f, Font, 1.f);
}
